import{a,_ as t}from"./chunks/wms-preview.DQ5M_5xo.js";import{_ as r,o,c as d,a2 as i}from"./chunks/framework.CqGPl1zp.js";const l="/newx-doc/img/WMS%E6%89%8B%E5%86%8C/%E7%A7%BB%E5%8A%A8%E7%AB%AF/%E5%B7%A5%E4%BD%9C%E5%8F%B0.png",s="/newx-doc/img/ad/zsxq_wms.png",h="/newx-doc/img/WMS%E6%89%8B%E5%86%8C/%E5%8A%9F%E8%83%BD%E6%BC%94%E7%A4%BA/%E8%A1%A8%E5%85%B3%E7%B3%BB.png",S=JSON.parse('{"title":"WMS 演示","description":"","frontmatter":{},"headers":[],"relativePath":"wms-preview.md","filePath":"wms-preview.md","lastUpdated":null}'),c={name:"wms-preview.md"};function m(n,e,u,p,_,w){return o(),d("div",null,[...e[0]||(e[0]=[i('<h1 id="wms-演示" tabindex="-1">WMS 演示 <a class="header-anchor" href="#wms-演示" aria-label="Permalink to &quot;WMS 演示&quot;">​</a></h1><h2 id="_1-演示地址" tabindex="-1">1. 演示地址 <a class="header-anchor" href="#_1-演示地址" aria-label="Permalink to &quot;1. 演示地址&quot;">​</a></h2><p>WMS（Warehouse Management System，仓库管理系统）用于管理企业仓库、商品与库存，围绕“仓库 + SKU”形成统一库存台账，并通过入库、出库、移库和盘库单据记录每一次库存变化。</p><h3 id="_1-1-wms-管理后台" tabindex="-1">1.1 WMS 管理后台 <a class="header-anchor" href="#_1-1-wms-管理后台" aria-label="Permalink to &quot;1.1 WMS 管理后台&quot;">​</a></h3><ul><li>演示地址：<a href="http://dashboard-vue3.yudao.iocoder.cn/" target="_blank" rel="noreferrer">http://dashboard-vue3.yudao.iocoder.cn/</a></li><li>菜单：&quot;WMS 系统&quot;下的「基础数据」「库存管理」「入库管理」「出库管理」「移库管理」「盘库管理」</li><li>仓库：<a href="https://github.com/yudaocode/yudao-ui-admin-vue3" target="_blank" rel="noreferrer">https://github.com/yudaocode/yudao-ui-admin-vue3</a> 的 <code>wms</code> 目录，基于 Vue3 + Element Plus 实现</li></ul><p><img src="'+a+'" alt="管理后台"></p><h3 id="_1-2-wms-后端" tabindex="-1">1.2 WMS 后端 <a class="header-anchor" href="#_1-2-wms-后端" aria-label="Permalink to &quot;1.2 WMS 后端&quot;">​</a></h3><p>支持 Spring Boot 单体、Spring Cloud 微服务架构</p><ul><li>单体仓库：<a href="https://github.com/YunaiV/ruoyi-vue-pro" target="_blank" rel="noreferrer">https://github.com/YunaiV/ruoyi-vue-pro</a> 的 <code>yudao-module-wms</code> 模块</li><li>微服务仓库：<a href="https://github.com/YunaiV/yudao-cloud" target="_blank" rel="noreferrer">https://github.com/YunaiV/yudao-cloud</a> 的 <code>yudao-module-wms</code> 服务</li></ul><h3 id="_1-3-wms-移动端" tabindex="-1">1.3 WMS 移动端 <a class="header-anchor" href="#_1-3-wms-移动端" aria-label="Permalink to &quot;1.3 WMS 移动端&quot;">​</a></h3><p>WMS 提供 uni-app 移动端，仓库、商品、库存和出入库单据都可以在手机上处理，详见 <a href="./wms/mobile">《移动端 WMS》</a>。</p><ul><li>仓库：<a href="https://github.com/yudaocode/yudao-ui-admin-uniapp" target="_blank" rel="noreferrer">https://github.com/yudaocode/yudao-ui-admin-uniapp</a> 的 <code>pages-wms</code> 目录</li></ul><p><img src="'+l+'" alt="移动端"></p><h2 id="_2-wms-启动" tabindex="-1">2. WMS 启动 <a class="header-anchor" href="#_2-wms-启动" aria-label="Permalink to &quot;2. WMS 启动&quot;">​</a></h2><p>参见 <a href="./wms/build">《WMS 手册 —— 功能开启》</a> 文档，一般 3 分钟就可以启动完成。</p><h2 id="_3-wms-交流" tabindex="-1">3. WMS 交流 <a class="header-anchor" href="#_3-wms-交流" aria-label="Permalink to &quot;3. WMS 交流&quot;">​</a></h2><p>专属交流社区，欢迎扫码加入。</p><p><img src="'+s+'" alt="交流群"></p><h2 id="_4-功能描述" tabindex="-1">4. 功能描述 <a class="header-anchor" href="#_4-功能描述" aria-label="Permalink to &quot;4. 功能描述&quot;">​</a></h2><p>主要包含：基础数据、库存管理，以及入库 / 出库 / 移库 / 盘库四类业务单据。</p><p><img src="'+t+'" alt="WMS 功能列表"></p><h2 id="_5-表结构" tabindex="-1">5. 表结构 <a class="header-anchor" href="#_5-表结构" aria-label="Permalink to &quot;5. 表结构&quot;">​</a></h2><p>WMS 共 <strong>16</strong> 张表，覆盖物料主数据、库存台账与流水、出入库 / 移库 / 盘库四类业务单据，表名统一以 <code>wms_</code> 为前缀：</p><p><img src="'+h+'" alt="WMS 全表关系"></p><table tabindex="0"><thead><tr><th>模块</th><th>子前缀</th><th>表数量</th><th>核心职责</th></tr></thead><tbody><tr><td>基础数据</td><td><code>wms_warehouse</code> / <code>wms_item*</code> / <code>wms_merchant</code></td><td>6</td><td>仓库、商品体系（分类 / 品牌 / 商品 / SKU）、往来企业</td></tr><tr><td>库存管理</td><td><code>wms_inventory*</code></td><td>2</td><td>当前库存数量记录（按 <code>仓库 + SKU</code> 聚合）+ 库存变更流水</td></tr><tr><td>入库单</td><td><code>wms_receipt_order*</code></td><td>2</td><td>生产 / 采购 / 退货 / 归还 四类入库，共主表 + 明细</td></tr><tr><td>出库单</td><td><code>wms_shipment_order*</code></td><td>2</td><td>退货 / 销售 / 生产 三类出库，共主表 + 明细</td></tr><tr><td>移库单</td><td><code>wms_movement_order*</code></td><td>2</td><td>同公司内不同仓库间转移物料（主表 + 明细）</td></tr><tr><td>盘库单</td><td><code>wms_check_order*</code></td><td>2</td><td>实物盘点后调整账面库存差异（主表 + 明细）</td></tr></tbody></table><h3 id="_5-1-基础数据" tabindex="-1">5.1 基础数据 <a class="header-anchor" href="#_5-1-基础数据" aria-label="Permalink to &quot;5.1 基础数据&quot;">​</a></h3><p>为库存与单据业务提供主数据支撑，包括仓库、商品体系（分类、品牌、商品、SKU）、往来企业（供应商、客户）。</p><ul><li><a href="./wms/md/warehouse">《【基础】仓库》</a></li><li><a href="./wms/md/item">《【基础】商品、SKU、分类、品牌》</a></li><li><a href="./wms/md/merchant">《【基础】往来企业（供应商、客户）》</a></li></ul><h3 id="_5-2-库存管理" tabindex="-1">5.2 库存管理 <a class="header-anchor" href="#_5-2-库存管理" aria-label="Permalink to &quot;5.2 库存管理&quot;">​</a></h3><p>按 <code>仓库 + SKU</code> 维度记录当前库存数量，所有出入库 / 移库 / 盘库单据完成时通过库存事务统一写入流水。首页报表基于库存记录与流水聚合关键指标。</p><ul><li><a href="./wms/inventory">《【库存】库存记录、流水、统计》</a></li></ul><h3 id="_5-3-单据管理" tabindex="-1">5.3 单据管理 <a class="header-anchor" href="#_5-3-单据管理" aria-label="Permalink to &quot;5.3 单据管理&quot;">​</a></h3><p>四类业务单据：</p><ul><li><strong>入库单</strong>（<code>wms_receipt_order*</code>）：生产 / 采购 / 退货 / 归还四类，共用主表 + 明细。</li><li><strong>出库单</strong>（<code>wms_shipment_order*</code>）：退货 / 销售 / 生产三类，共用主表 + 明细。</li><li><strong>移库单</strong>（<code>wms_movement_order*</code>）：同公司内不同仓库间转移物料，完成时一次性写入 OUT + IN 两笔库存事务。</li><li><strong>盘库单</strong>（<code>wms_check_order*</code>）：实物盘点对比账面后，按差异写入 ADJUST 库存事务对齐账实。</li><li><a href="./wms/order/receipt">《【单据】入库》</a></li><li><a href="./wms/order/shipment">《【单据】出库》</a></li><li><a href="./wms/order/movement">《【单据】移库》</a></li><li><a href="./wms/order/check">《【单据】盘库》</a></li></ul><h2 id="_6-选型参考" tabindex="-1">6. 选型参考 <a class="header-anchor" href="#_6-选型参考" aria-label="Permalink to &quot;6. 选型参考&quot;">​</a></h2><p>yudao 体系内 WMS、MES、ERP 三个模块均涉及&quot;库存&quot;与&quot;出入库单据&quot;，业务边界与技术深度差异较大。选型纠结时可参阅：</p><ul><li><a href="./wms/compare">《【其它】WMS、MES、ERP 对比》</a></li></ul>',37)])])}const g=r(c,[["render",m]]);export{S as __pageData,g as default};
